package com.my.newproject;

import android.app.Activity;
import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.util.Base64;
import android.view.View;
import android.widget.ImageView;
import android.widget.LinearLayout;
import android.widget.TextView;

import org.json.JSONObject;

import java.util.ArrayList;
import java.util.Locale;

/**
 * The channels that used to live INSIDE the Cigram app (CigramBuiltinChannels in the app project):
 * الشرقية and beIN SPORTS 3. They were written into the app's code, so the admin could not see, edit or
 * delete them. The channels page shows a card while any of them is missing from the channels Worker,
 * and one tap adds them there (POST /channels/add, same as the "add channel" screen) with their logo.
 * After that they are ordinary channels: link change, delete, hide, test, notes, order.
 *
 * { name, stream link, kind ("sports" / "news"), section used when no matching section exists, logo }
 */
final class CgBuiltinChannels {

    private static final String LOGO_SHARQIYA = "";
    private static final String LOGO_BEIN3 = "";

    static final String[][] LIST = {
        {"الشرقية", "https://5d94523502c2d.streamlock.net/home/mystream/chunklist_w1496386509.m3u8", "news", "الأخبارية", LOGO_SHARQIYA},
        {"beIN SPORTS 3", "http://194.76.0.163/8zpo3GsVY7/beneficial2concern/652335?token=ShJdY2ZmQQNHCmMZCDZXUh9GSHAWGFMD.ZDsGQVN.", "sports", "الرياضة", LOGO_BEIN3},
    };

    private CgBuiltinChannels() { }

    /** Same key as the app (CigramChannelStore.norm): a channel with this name is the same channel. */
    static String norm(String v) {
        if (v == null) return "";
        return v.trim().toLowerCase(Locale.US)
                .replace("أ", "ا").replace("إ", "ا").replace("آ", "ا")
                .replace("ة", "ه").replace("ى", "ي")
                .replaceAll("[\\s_\\-]+", "");
    }

    /** The built-in channels whose name is not on the channels Worker yet (list items: {name, category, ...}). */
    static ArrayList<String[]> missing(ArrayList<JSONObject> channels) {
        ArrayList<String> have = new ArrayList<String>();
        for (int i = 0; i < channels.size(); i++) have.add(norm(channels.get(i).optString("name")));
        ArrayList<String[]> out = new ArrayList<String[]>();
        for (int i = 0; i < LIST.length; i++) {
            if (!have.contains(norm(LIST[i][0]))) out.add(LIST[i]);
        }
        return out;
    }

    /** An existing section of the same kind (e.g. «رياضة» or «Sports»), else the default name. */
    static String categoryFor(String[] ch, ArrayList<JSONObject> channels) {
        for (int i = 0; i < channels.size(); i++) {
            String cat = channels.get(i).optString("category");
            String k = norm(cat);
            if (k.length() == 0) continue;
            if ("sports".equals(ch[2]) && (k.contains("رياض") || k.contains("sport"))) return cat;
            if ("news".equals(ch[2]) && (k.contains("اخبار") || k.contains("خبر") || k.contains("news"))) return cat;
        }
        return ch[3];
    }

    static Bitmap logo(String[] ch) {
        try {
            byte[] b = Base64.decode(ch[4], Base64.DEFAULT);
            return BitmapFactory.decodeByteArray(b, 0, b.length);
        } catch (Throwable t) {
            return null;
        }
    }

    /** Adds one channel to the channels Worker. Background thread. */
    static void add(String[] ch, String category) throws Exception {
        JSONObject body = new JSONObject();
        body.put("category", category);
        body.put("name", ch[0]);
        body.put("url", ch[1]);
        body.put("image_base64", ch[4]);
        body.put("image_mime", "image/jpeg");
        CgHttp.Res r = CgHttp.call("POST", CgCfg.CHANNELS_API + "/channels/add", body, false, 60000,
                new String[][]{{"X-Admin-Token", CgCfg.TOKEN}});
        if (r.error != null) throw new Exception(CgHttp.describe(r.error));
        if (r.code == 401 || r.code == 403) throw new Exception("رمز الإدارة غير مقبول في Worker القنوات.");
        if (!r.ok()) throw new Exception("تعذرت إضافة «" + ch[0] + "»: " + r.message());
    }

    /** The card on the channels page: what is missing, and one button that adds it. */
    static View card(Activity a, ArrayList<String[]> missing, ArrayList<JSONObject> channels, final Runnable onAdd) {
        LinearLayout box = CgUi.card(a);
        box.setBackground(CgUi.bg(a, CgCfg.CARD, 14, CgCfg.WARN));
        box.addView(CgUi.text(a, missing.size() == 1 ? "قناة داخل التطبيق غير موجودة في الإدارة"
                : "قنوات داخل التطبيق غير موجودة في الإدارة", 15, CgCfg.TEXT, true));
        box.addView(CgUi.muted(a, "هذه القنوات مكتوبة داخل كود تطبيق سيكرام، فلا تظهر هنا ولا يمكن تعديلها أو حذفها. "
                + "أضفها للإدارة لتتحكم بها مثل باقي القنوات: تغيير الرابط، الحذف، الإخفاء، والفحص."),
                CgUi.lp(a, CgUi.MATCH, CgUi.WRAP, 0, 4, 0, 6));
        for (int i = 0; i < missing.size(); i++) {
            String[] ch = missing.get(i);
            LinearLayout row = CgUi.hbox(a);
            ImageView img = new ImageView(a);
            img.setScaleType(ImageView.ScaleType.CENTER_INSIDE);
            Bitmap b = logo(ch);
            if (b != null) img.setImageBitmap(b);
            LinearLayout.LayoutParams ilp = new LinearLayout.LayoutParams(CgUi.dp(a, 44), CgUi.dp(a, 44));
            ilp.setMargins(0, 0, CgUi.dp(a, 10), 0);
            row.addView(img, ilp);
            LinearLayout col = CgUi.vbox(a);
            col.addView(CgUi.text(a, ch[0], 14, CgCfg.TEXT, true));
            String note = "القسم: " + categoryFor(ch, channels);
            if (ch[1].startsWith("http://")) note += " · رابط http (يعمل في التطبيق فقط، لا في الموقع)";
            col.addView(CgUi.muted(a, note));
            row.addView(col, new LinearLayout.LayoutParams(0, CgUi.WRAP, 1f));
            box.addView(row, CgUi.lp(a, CgUi.MATCH, CgUi.WRAP, 0, 6, 0, 0));
        }
        TextView add = CgUi.button(a, missing.size() == 1 ? "إضافة القناة للإدارة" : "إضافة القنوات للإدارة (" + missing.size() + ")", 0);
        add.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                onAdd.run();
            }
        });
        box.addView(add, CgUi.lp(a, CgUi.MATCH, CgUi.WRAP, 0, 12, 0, 0));
        return box;
    }
}
